const clientes =
  $json.body?.clientes ??
  $json.corpo?.clientes ??
  $json.clientes ??
  [];

if (!Array.isArray(clientes) || clientes.length === 0) {
  throw new Error('Nenhum cliente foi recebido pelo Webhook.');
}

return clientes.map(cliente => ({
  json: {
    nome: cliente.nome,
    email: cliente.email,
    saldo: cliente.saldo,
    perfil: cliente.perfil
  }
}));

const csv = String(
  $json.dados ??
  $json.data ??
  $json.body ??
  ''
).trim();

if (!csv) {
  throw new Error('O conteúdo do CSV não foi recebido.');
}

const linhas = csv
  .split(/\r?\n/)
  .map(linha => linha.trim())
  .filter(Boolean);

// Remove o cabeçalho
linhas.shift();

return linhas.map(linha => {
  const partes = linha.split(',');

  const perfil = partes.shift()?.trim();
  const produto = partes.shift()?.trim();
  const minimoTexto = partes.shift()?.trim();

  // Junta o restante porque uma rentabilidade como IPCA+6,0%
  // pode conter vírgula.
  const rentabilidade = partes.join(',').trim();

  const minimo = Number(minimoTexto);

  return {
    json: {
      perfil,
      produto,
      minimo,
      rentabilidade
    }
  };
});

return $input.all()
  .filter(item => {
    const saldoTexto = String(item.json.saldo ?? '0');

    // "R$ 12.500,00" -> 12500
    const saldo = Number(
      saldoTexto
        .replace('R$', '')
        .replace(/\./g, '')
        .replace(',', '.')
        .trim()
    );

    const minimo = Number(
      item.json['mínimo'] ??
      item.json.minimo ??
      0
    );

    return saldo >= minimo;
  })
  .map(item => ({
    json: {
      ...item.json,
      saldoNumerico: Number(
        String(item.json.saldo ?? '0')
          .replace('R$', '')
          .replace(/\./g, '')
          .replace(',', '.')
          .trim()
      )
    }
  }));

const grupos = new Map();

for (const item of $input.all()) {
  const j = item.json;

  const email = String(
    j['e-mail'] ??
    j.email ??
    ''
  ).trim();

  // Usamos o e-mail como identificador principal do cliente.
  // Se estiver vazio, usamos o nome.
  const chave = email || j.nome;

  if (!grupos.has(chave)) {
    grupos.set(chave, {
      nome: j.nome,
      email,
      saldo: j.saldo,
      saldoNumerico: j.saldoNumerico,
      perfil: j.perfil,
      investimentos: []
    });
  }

  grupos.get(chave).investimentos.push({
    produto: j.produto,
    minimo: Number(
      j['mínimo'] ??
      j.minimo ??
      0
    ),
    rentabilidade: j.rentabilidade
  });
}

return Array.from(grupos.values()).map(cliente => ({
  json: cliente
}));

const cliente = $json;

const investimentosTexto = cliente.investimentos
  .map((inv, i) =>
    `${i + 1}. ${inv.produto}
   Aplicação mínima: R$ ${Number(inv.minimo).toLocaleString('pt-BR')}
   Rentabilidade informada: ${inv.rentabilidade}`
  )
  .join('\n\n');

const prompt = `
Crie um briefing educacional de investimentos para o cliente abaixo.

CLIENTE
Nome: ${cliente.nome}
Perfil: ${cliente.perfil}
Saldo disponível: ${cliente.saldo}

OPÇÕES COMPATÍVEIS COM O PERFIL E O SALDO
${investimentosTexto}

O briefing deve:
- ser escrito em português do Brasil;
- explicar de forma simples as opções apresentadas;
- considerar o perfil informado;
- explicar diferenças de risco, liquidez e características gerais;
- não inventar taxas nem produtos;
- utilizar somente os dados recebidos;
- não apresentar ordem direta de compra ou venda;
- deixar claro que o conteúdo é educacional.

Organize a resposta com:
1. Saudação personalizada
2. Resumo do perfil
3. Opções disponíveis
4. Pontos de atenção
5. Conclusão educacional
`;

return {
  json: {
    ...cliente,
    prompt
  }
};

parameters.content:
## 1. Entrada RPA e Base de Investimentos

Recebe via Webhook os clientes extraídos pelo script Python no Google Colab.




















Em paralelo:
- separa os dados dos clientes;
- carrega a base de investimentos;
- interpreta os produtos disponíveis;
- combina clientes e investimentos pelo perfil do investidor.

## 2. Regras de Negócio e Preparação para IA

Aplica as regras do projeto antes do envio para o agente de IA.









Etapas:
- filtra apenas investimentos compatíveis com o saldo do cliente;
- agrupa as opções elegíveis por cliente;
- prepara um prompt personalizado com nome, perfil, saldo e investimentos disponíveis;
- limita a quantidade de clientes processados durante os testes.

## 3. IA Generativa

Recebe o prompt personalizado de cada cliente e gera um briefing educacional de investimentos.


















O agente considera:
- perfil do investidor;
- saldo disponível;
- produtos compatíveis encontrados;
- regras de segurança definidas no prompt.

A resposta é gerada dinamicamente por um modelo LLM e possui finalidade educacional.
